var visual = (function () {
  var BORDER = '#c9d6e6';
  var INK = '#16324f';
  var MUTED = '#42566e';
  var ARROW = '#7d8ea3';

  var STEPS = [
    { name: '第一步：移项', eq: '2x - 5x = 7 - 3', color: '#2f6fb2' },
    { name: '第二步：合并同类项', eq: '-3x = 4', color: '#2f8a5b' },
    { name: '第三步：系数化为 1', eq: 'x = 4 ÷ (-3) = -4/3', color: '#b87333' }
  ];

  function axisLine(x1, y1, x2, y2) {
    return visualSdk.axis({ x0: x1, y0: y1, x1: x2, y1: y2, ticks: 0, tickLength: 0 });
  }

  return {
    prepare: function (input) {
      var list = [{ kind: 'text', payload: '解一元一次方程  2x + 3 = 5x + 7' }];
      var i;
      for (i = 0; i < STEPS.length; i++) {
        list.push({ kind: 'text', payload: STEPS[i].name });
        list.push({ kind: 'text', payload: STEPS[i].eq });
      }
      return list;
    },

    render: function (input, metrics) {
      var vp = (input && input.viewport) || {};
      var W = vp.widthDu || 720;
      var H = vp.heightDu || 520;

      var pad = Math.round(W * 0.055);
      var cardX = pad;
      var cardW = W - pad * 2;
      var titleY = Math.round(H * 0.10);
      var cardsTop = H * 0.185;
      var cardsBottom = H * 0.93;
      var gap = Math.max(16, H * 0.06);
      var cardH = (cardsBottom - cardsTop - gap * 2) / 3;

      var paths = [];
      var children = [];

      function addLine(id, x1, y1, x2, y2, color, w) {
        paths.push({ id: id, commands: axisLine(x1, y1, x2, y2) });
        children.push({ type: 'path', pathId: id, fill: color, stroke: { width: w, color: color } });
      }

      function addDot(id, cx, cy, r, color) {
        paths.push({ id: id, commands: visualSdk.circle(cx, cy, r) });
        children.push({ type: 'path', pathId: id, fill: color, stroke: { width: 1, color: color } });
      }

      function addArrow(id, x1, y1, x2, y2) {
        paths.push({ id: id, commands: visualSdk.arrow(x1, y1, x2, y2, {}) });
        children.push({ type: 'path', pathId: id, fill: ARROW, stroke: { width: 1.5, color: ARROW } });
      }

      var i;
      var cardY;
      var dotR = Math.max(5, cardH * 0.062);

      for (i = 0; i < STEPS.length; i++) {
        cardY = cardsTop + i * (cardH + gap);
        addLine('top' + i, cardX, cardY, cardX + cardW, cardY, BORDER, 1.5);
        addLine('bot' + i, cardX, cardY + cardH, cardX + cardW, cardY + cardH, BORDER, 1.5);
        addLine('rgt' + i, cardX + cardW, cardY, cardX + cardW, cardY + cardH, BORDER, 1.5);
        addLine('acc' + i, cardX, cardY, cardX, cardY + cardH, STEPS[i].color, 5);
        addDot('dot' + i, cardX + cardW * 0.05, cardY + cardH * 0.28, dotR, STEPS[i].color);
      }

      for (i = 0; i < STEPS.length - 1; i++) {
        var yStart = cardsTop + i * (cardH + gap) + cardH + 4;
        var yEnd = cardsTop + (i + 1) * (cardH + gap) - 4;
        addArrow('arr' + i, W / 2, yStart, W / 2, yEnd);
      }

      children.push({ type: 'label', contentId: 'c0', anchor: { x: W / 2, y: titleY },
        hAlign: 'center', vAlign: 'middle', color: INK, fontSize: Math.round(H * 0.042) });

      for (i = 0; i < STEPS.length; i++) {
        cardY = cardsTop + i * (cardH + gap);
        children.push({ type: 'label', contentId: 'c' + (1 + i * 2),
          anchor: { x: cardX + cardW * 0.05 + dotR + 10, y: cardY + cardH * 0.28 },
          hAlign: 'left', vAlign: 'middle', color: MUTED, fontSize: Math.round(H * 0.032) });
        children.push({ type: 'label', contentId: 'c' + (2 + i * 2),
          anchor: { x: cardX + cardW * 0.075, y: cardY + cardH * 0.70 },
          hAlign: 'left', vAlign: 'middle', color: INK, fontSize: Math.round(H * 0.038) });
      }

      return {
        schemaVersion: 1,
        sceneId: 'linear-eq-steps',
        revision: input.revision,
        viewBox: { x: 0, y: 0, width: W, height: H },
        paths: paths,
        root: { type: 'group', children: children }
      };
    }
  };
})();
